CREATE TABLE IF NOT EXISTS rooms (id SERIAL PRIMARY KEY, number VARCHAR(10) NOT NULL, type VARCHAR(20) NOT NULL, beds INTEGER NOT NULL, occupied INTEGER NOT NULL, status VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id SERIAL PRIMARY KEY, guest_name VARCHAR(80) NOT NULL, room_number VARCHAR(10) NOT NULL, check_in DATE NOT NULL, check_out DATE NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id SERIAL PRIMARY KEY, guest_name VARCHAR(80) NOT NULL, invoice VARCHAR(20) NOT NULL, amount DECIMAL(10, 2) NOT NULL, status VARCHAR(20) NOT NULL, due_date DATE NOT NULL);
CREATE TABLE IF NOT EXISTS staff (id SERIAL PRIMARY KEY, name VARCHAR(80) NOT NULL, role VARCHAR(40) NOT NULL, shift VARCHAR(40) NOT NULL, on_duty BOOLEAN DEFAULT true);
CREATE TABLE IF NOT EXISTS maintenance_tickets (id SERIAL PRIMARY KEY, issue VARCHAR(120) NOT NULL, room_number VARCHAR(10) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS occupancy_trend (id SERIAL PRIMARY KEY, month_label VARCHAR(12) NOT NULL, rate INTEGER NOT NULL, sort_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS room_status_overview (id SERIAL PRIMARY KEY, label VARCHAR(30) NOT NULL, value INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(120) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'user', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS hostels (id SERIAL PRIMARY KEY, owner_id INTEGER, name VARCHAR(100) NOT NULL, area VARCHAR(80) NOT NULL, city VARCHAR(80) NOT NULL, address VARCHAR(180) NOT NULL, lat DECIMAL(10, 6) NOT NULL, lng DECIMAL(10, 6) NOT NULL, gender VARCHAR(20) NOT NULL DEFAULT 'co-ed', description TEXT, phone VARCHAR(40), email VARCHAR(120), approved BOOLEAN DEFAULT false, is_active BOOLEAN DEFAULT true, FOREIGN KEY (owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS hostel_rooms (id SERIAL PRIMARY KEY, hostel_id INTEGER NOT NULL, room_type VARCHAR(20) NOT NULL, occupants_per_room INTEGER NOT NULL, beds_total INTEGER NOT NULL, beds_available INTEGER NOT NULL, available_from DATE NOT NULL, available_to DATE NOT NULL, rent DECIMAL(10, 2) NOT NULL, FOREIGN KEY (hostel_id) REFERENCES hostels(id));
CREATE TABLE IF NOT EXISTS hostel_images (id SERIAL PRIMARY KEY, hostel_id INTEGER NOT NULL, url VARCHAR(255) NOT NULL, FOREIGN KEY (hostel_id) REFERENCES hostels(id));
CREATE TABLE IF NOT EXISTS hostel_facilities (id SERIAL PRIMARY KEY, hostel_id INTEGER NOT NULL, name VARCHAR(80) NOT NULL, FOREIGN KEY (hostel_id) REFERENCES hostels(id));
CREATE TABLE IF NOT EXISTS hostel_rules (id SERIAL PRIMARY KEY, hostel_id INTEGER NOT NULL, rule VARCHAR(160) NOT NULL, FOREIGN KEY (hostel_id) REFERENCES hostels(id));
CREATE TABLE IF NOT EXISTS owner_subscriptions (id SERIAL PRIMARY KEY, user_id INTEGER NOT NULL, plan_id VARCHAR(30) NOT NULL, status VARCHAR(20) NOT NULL, payment_method VARCHAR(40) NOT NULL, transaction_ref VARCHAR(120), started_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, expires_at TIMESTAMP NULL, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_favorites (user_id INTEGER NOT NULL, hostel_id INTEGER NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, hostel_id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (hostel_id) REFERENCES hostels(id));
